#!/usr/bin/env bash
# Generated by fmverify. Fetches the z3 CLI used to run fmtranslator's bounded SMT-LIB claims.
#
# This is the CLI, not the Microsoft.Z3 package the model uses. It is a pinned GitHub release
# asset, hash-verified before use, and it lands in .tools/ so nothing is installed globally or
# looked up on PATH. The script is only run by verify.sh when a translation/ directory exists.
set -euo pipefail
cd "$(dirname "$0")"

VERSION="5.3.3"

case "$(uname -s)-$(uname -m)" in
  Linux-x86_64)            ASSET="z3-5.3.3-x64-glibc-2.39.zip";   SHA256="d56f60b06f432f33de5810f7f1a384a339131f361e2d54d08ea83eea14326880" ;;
  Linux-aarch64)           ASSET="z3-5.3.3-arm64-glibc-2.38.zip"; SHA256="d4586e12af2609499e07d615ac578256125b19f396f0d6ca358fe7b22988bcec" ;;
  Darwin-x86_64)           ASSET="z3-5.3.3-x64-osx-13.3.zip";     SHA256="ace69787d5a21762154b103abe68178188f38e02362fb0f82d346621af90f8e7" ;;
  Darwin-arm64)            ASSET="z3-5.3.3-arm64-osx-13.3.zip";   SHA256="6957e6c75266d7ca8fa77030e86e83d78624567dcdf34cc11f4192fdc6f93c6b" ;;
  MINGW*-x86_64|MSYS*-x86_64|CYGWIN*-x86_64)
                           ASSET="z3-5.3.3-x64-win.zip"; SHA256="4e48624a6895b49606b3cf91ca4fbcc069fb2973b9706532170a144baa3fd798" ;;
  *)
    echo "ERROR: z3 $VERSION has no CLI release for $(uname -s)-$(uname -m)." >&2
    exit 1 ;;
esac

URL="https://github.com/Z3Prover/z3/releases/download/z3-${VERSION}/${ASSET}"
TOOLS=".tools"
ZIP="$TOOLS/$ASSET"
INSTALL="$TOOLS/z3-$VERSION"

actual_sha() {
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1
  else shasum -a 256 "$1" | cut -d' ' -f1
  fi
}

mkdir -p "$TOOLS"

if ! { [ -f "$ZIP" ] && [ "$(actual_sha "$ZIP")" = "$SHA256" ]; }; then
  echo "Fetching z3 $VERSION from $URL"
  curl -fsSL -o "$ZIP" "$URL"

  ACTUAL="$(actual_sha "$ZIP")"
  if [ "$ACTUAL" != "$SHA256" ]; then
    rm -f "$ZIP"
    echo "ERROR: z3 package hash mismatch. Refusing to use it." >&2
    echo "  expected $SHA256" >&2
    echo "  actual   $ACTUAL" >&2
    exit 1
  fi

  rm -rf "$INSTALL"
fi

# A directory left by an interrupted extraction is not accepted.
if [ ! -x "$INSTALL/bin/z3" ] && [ ! -x "$INSTALL/bin/z3.exe" ]; then
  rm -rf "$INSTALL" "$INSTALL.partial"
  unzip -q "$ZIP" -d "$INSTALL.partial"

  # POSIX glob rather than find: macOS ships BSD find without -maxdepth/-mindepth.
  ROOT=""
  for candidate in "$INSTALL.partial"/*/; do
    if [ -d "$candidate" ]; then ROOT="${candidate%/}"; break; fi
  done

  if [ -z "$ROOT" ] || { [ ! -f "$ROOT/bin/z3" ] && [ ! -f "$ROOT/bin/z3.exe" ]; }; then
    rm -rf "$INSTALL.partial"
    echo "ERROR: z3 archive did not contain bin/z3." >&2
    exit 1
  fi

  mv "$ROOT" "$INSTALL"
  rm -rf "$INSTALL.partial"
fi

if [ -f "$INSTALL/bin/z3" ]; then
  chmod +x "$INSTALL/bin/z3"
elif [ -f "$INSTALL/bin/z3.exe" ]; then
  chmod +x "$INSTALL/bin/z3.exe"
else
  echo "ERROR: z3 binary is missing after extraction." >&2
  exit 1
fi

echo "z3 $VERSION present and verified."
